from config_core import *
from json_text import *
from ail import write_stdout_bytes
import sys

class ConfigFailure:

    def __init__(self, path: str, error: exception):
        self.path = path
        self.error = error

class ConfigBatch:

    def __init__(self, errors: list[exception], paths: list[str], reports: list[str]):
        self.errors = errors
        self.paths = paths
        self.reports = reports

def validate_many(paths: list[str]) -> ConfigBatch:
    errors: list[exception] = []
    failed_paths: list[str] = []
    reports: list[str] = []
    for path in paths:
        try:
            report = validate_config(path)
            reports.append('{"path":' + json_quote(path) + ',"summary":' + report + '}')
        except (ValueError, OSError) as error:
            errors.append(error)
            failed_paths.append(path)
    return ConfigBatch(errors, failed_paths, reports)

def merge_config_batches(left: ConfigBatch, right: ConfigBatch) -> ConfigBatch:
    left.errors.extend(right.errors)
    left.paths.extend(right.paths)
    left.reports.extend(right.reports)
    return left

def failure_json(failure: ConfigFailure) -> str:
    return '{"path":' + json_quote(failure.path) + ',"kind":' + json_quote(failure.error.kind) + ',"message":' + json_quote(failure.error.message) + '}'

def batch_json(batch: ConfigBatch) -> str:
    errors: list[str] = []
    for i in range(len(batch.errors)):
        failure = ConfigFailure(batch.paths[i], batch.errors[i])
        errors.append(failure_json(failure))
    return '{"reports":[' + ','.join(batch.reports) + '],"errors":[' + ','.join(errors) + ']}'

def main() -> int:
    if len(sys.argv) < 2:
        print('usage: config_batch INPUT...', file=sys.stderr)
        return 2
    batch = validate_many(sys.argv[1:])
    write_stdout_bytes((batch_json(batch) + '\n').encode())
    if len(batch.errors) > 0:
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
